// Function to clean PII from email
function cleanEmailForAI(content) {
  if (!content) return '';

  let cleaned = content;

  // Remove email addresses
  cleaned = cleaned.replace(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g, '[EMAIL]');

  // Remove phone numbers
  cleaned = cleaned.replace(/\b\d{3}[-.]?\d{3}[-.]?\d{4}\b/g, '[PHONE]');

  // Remove names in salutations
  cleaned = cleaned.replace(/Dear\s+[A-Z][a-z]+(\s+[A-Z][a-z]+)?/g, 'Dear [NAME]');
  cleaned = cleaned.replace(/Hi\s+[A-Z][a-z]+/g, 'Hi [NAME]');

  return cleaned;
}

// Extract removal ID in format: ID-V10192G
// Pattern: ID- followed by letter + 6 alphanumeric characters
function extractRemovalId(text) {
  if (!text) return null;

  // Pattern: ID- + one letter + exactly 6 alphanumeric characters
  const pattern = /ID-[A-Z0-9]{7}\b/i;

  const match = text.match(pattern);

  if (match) {
    // Return uppercase version for consistency
    return match[0].toUpperCase();
  }

  return null;
}

